# PTX source for L2‑normalization across dim=1 (fp16 input/output)
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry l2norm_kernel (
    .param .u64 x_ptr,
    .param .u64 y_ptr,
    .param .u32 batch,
    .param .u32 dim
)
{
    // ----- Registers -----
    .reg .pred   %p<2>;
    .reg .s32    %r<15>;
    .reg .s64    %rd<9>;
    .reg .f32    %f<6>;
    .reg .f16    %h<4>;

    // ----- Load kernel parameters -----
    ld.param.u64    %rd1, [x_ptr];
    ld.param.u64    %rd2, [y_ptr];
    ld.param.u32    %r1,  [batch];
    ld.param.u32    %r2,  [dim];

    // ----- Compute thread / block indices -----
    mov.u32         %r3,  %ctaid.x;          // blockIdx.x  (row index)
    setp.ge.u32     %p0, %r3, %r1;          // if row >= batch, exit
    @%p0 bra        DONE;

    mov.u32         %r4,  %tid.x;           // threadIdx.x
    mov.u32         %r5,  %ntid.x;          // blockDim.x

    // ----- Compute base pointer for this row -----
    mul.wide.u32    %rd3, %r3, %r2;         // row * dim (as 64‑bit)
    mul.wide.u32    %rd4, %rd3, 2;          // * sizeof(fp16) == 2
    add.u64         %rd5, %rd1, %rd4;       // &x[row,0]
    add.u64         %rd6, %rd2, %rd4;       // &y[row,0]

    // ----- First pass: compute sum of squares (float32) -----
    mov.f32         %f0, 0.0;
    // loop over columns with stride = blockDim.x
LOOP_SUM:
    setp.ge.u32     %p1, %r4, %r2;
    @%p1 bra        END_SUM;
    mul.wide.u32    %rd7, %r4, 2;           // col * sizeof(fp16)
    add.u64         %rd8, %rd5, %rd7;       // address of x[row,col]
    ld.global.f16   %h0, [%rd8];
    cvt.rn.f32.f16  %f1, %h0;
    mul.f32         %f1, %f1, %f1;          // square
    add.f32         %f0, %f0, %f1;
    add.u32         %r4, %r4, %r5;          // col += stride
    bra.uni         LOOP_SUM;
END_SUM:

    // ----- Reduce partial sums within block -----
    .shared .align 4 .b32 sdata[256];
    st.shared.u32   [sdata+%r4*4], %f0;
    bar.sync 0;

    // binary tree reduction
    mov.u32         %r6, %ntid.x;
REDUCTION_LOOP:
    shr.u32         %r7, %r6, 1;            // offset = stride/2
    setp.eq.u32     %p1, %r7, 0;
    @%p1 bra        REDUCTION_DONE;
    setp.lt.u32     %p1, %r4, %r7;
    @%p1 {
        ld.shared.u32   %r8, [sdata+%r4*4];
        ld.shared.u32   %r9, [sdata+(%r4+%r7)*4];
        add.u32         %r8, %r8, %r9;
        st.shared.u32   [sdata+%r4*4], %r8;
    }
    bar.sync 0;
    mov.u32         %r6, %r7;
    bra.uni         REDUCTION_LOOP;
REDUCTION_DONE:

    // ----- Compute reciprocal of L2 norm -----
    ld.shared.u32   %r8, [sdata];          // sum of squares (as int bits of float)
    mov.b32         %f2, %r8;
    rsqrt.approx.f32 %f3, %f2;             // 1 / sqrt(sum)
    st.shared.u32   [sdata], %f3;         // broadcast reciprocal
    bar.sync 0;

    // ----- Second pass: write normalized values -----
    ld.shared.f32   %f4, [sdata];         // reciprocal (float)

    // reset column index
    mov.u32         %r4, %tid.x;
LOOP_WRITE:
    setp.ge.u32     %p1, %r4, %r2;
    @%p1 bra        END_WRITE;
    mul.wide.u32    %rd7, %r4, 2;
    add.u64         %rd8, %rd5, %rd7;      // src address
    ld.global.f16   %h1, [%rd8];
    cvt.rn.f32.f16  %f5, %h1;
    mul.f32         %f5, %f5, %f4;         // x * inv_norm
    cvt.rn.f16.f32  %h2, %f5;
    add.u64         %rd9, %rd6, %rd7;      // dst address
    st.global.f16   [%rd9], %h2;
    add.u32         %r4, %r4, %r5;
    bra.uni         LOOP_WRITE;
END_WRITE:

DONE:
    ret;
}
'''
# ------------------------------------------------------------------------------

class ModelNew:
    def __init__(self):
        # Load PTX module (ptx_harness provides ptx_load)
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x):
        """
        x : torch.cuda.HalfTensor of shape (batch, dim)
        returns torch.cuda.HalfTensor of same shape, L2‑normalized per row
        """
        batch, dim = x.shape
        y = torch.empty_like(x)

        # launch configuration: one block per row
        block = (256, 1, 1)
        grid  = (batch, 1, 1)

        args = [
            x.data_ptr(),          # const half* input
            y.data_ptr(),          # half* output
            int(batch),            # uint32 batch
            int(dim)               # uint32 dim
        ]

        # ptx_harness provides ptx_launch(module, kernel_name, grid, block, args)
        ptx_launch(self.module, "l2norm_kernel", grid, block, args)

        return y
